import{c as l,$ as o,Q as n,j as r,g as s,o as a,n as i,m as d}from"./chunks/framework.Ce_49mA8.js";const b=JSON.parse('{"title":"Обзор и философия личного капитала","description":"Концепция единого финансового контура мастера в ОмниКрафт ЕРП — разделение личных средств и кассы цеха, расчет расходов по балансовой дельте капитала.","frontmatter":{"title":"Обзор и философия личного капитала","description":"Концепция единого финансового контура мастера в ОмниКрафт ЕРП — разделение личных средств и кассы цеха, расчет расходов по балансовой дельте капитала.","datePublished":"2026-10-28","dateModified":"2026-11-19","order":14},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/overview.md","filePath":"ru/docs/spaces/moy-kapital/overview.md","lastUpdated":1795046400000}'),g={name:"ru/docs/spaces/moy-kapital/overview.md"},p={id:"обзор-и-философия-личного-капитала",tabindex:"-1"};function c(h,t,f,u,x,y){const e=o("DocIcon");return n(),r("div",null,[s("h1",p,[a(e,{name:"capital"}),t[0]||(t[0]=i(" Обзор и философия личного капитала ",-1)),t[1]||(t[1]=s("a",{class:"header-anchor",href:"#обзор-и-философия-личного-капитала","aria-label":'Permalink to "Обзор и философия личного капитала"'},"​",-1))]),t[2]||(t[2]=d('<p>Каждый ремесленник, мастер или руководитель небольшой студии неизбежно сталкивается с одной и той же дилеммой: где заканчиваются деньги мастерской и начинаются личные средства семьи?</p><p>Если закупка сырья, оплата аренды помещения, коммунальные платежи и семейные покупки в супермаркете оплачиваются с одной банковской карты, бизнес теряет прозрачность. Становится невозможно понять, приносит ли дело реальную чистую прибыль или держится на плаву только за счет постоянных вливаний из личных сбережений создателя.</p><p>В <strong>ОмниКрафт ЕРП</strong> пространство <strong>«Мой капитал»</strong> спроектировано для того, чтобы навести идеальный порядок на стыке между бизнесом и частной жизнью. Инструмент устраняет бухгалтерскую рутину и защищает мастера от утомительного ежедневного сбора кассовых чеков.</p><hr><h2 id="сравнение-подходов-к-учету-личных-финансов" tabindex="-1">Сравнение подходов к учету личных финансов <a class="header-anchor" href="#сравнение-подходов-к-учету-личных-финансов" aria-label="Permalink to &quot;Сравнение подходов к учету личных финансов&quot;">​</a></h2><p>Попытка вести личные финансы по законам операционного цеха или, наоборот, превращать производственную кассу в личный кошелек всегда оборачивается финансовым тупиком:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Критерий</th><th style="text-align:left;">Хаос единого кошелька</th><th style="text-align:left;">Модель ОмниКрафт ЕРП</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Финансовая граница</strong></td><td style="text-align:left;">Касса мастерской и личные деньги перемешаны на одной карте</td><td style="text-align:left;">Два изолированных контура: операционный цех и личный капитал</td></tr><tr><td style="text-align:left;"><strong>Учет личных расходов</strong></td><td style="text-align:left;">Ежедневный ручной ввод чеков за кофе, продукты и бытовые траты</td><td style="text-align:left;">Автоматический расчет расходов через балансовую дельту капитала</td></tr><tr><td style="text-align:left;"><strong>Оценка благосостояния</strong></td><td style="text-align:left;">Разрозненные остатки в нескольких мобильных банках и кошельках</td><td style="text-align:left;">Единая сводка чистых активов мастера с учетом долей в мастерских</td></tr><tr><td style="text-align:left;"><strong>Конфиденциальность</strong></td><td style="text-align:left;">Данные о личных счетах и вкладах рискуют попасть в отчеты цеха</td><td style="text-align:left;">Физически обособленная база данных <code>personal_finance.db</code></td></tr></tbody></table><hr><h2 id="принцип-двух-контуров-цех-и-карман-мастера" tabindex="-1">Принцип двух контуров: цех и карман мастера <a class="header-anchor" href="#принцип-двух-контуров-цех-и-карман-мастера" aria-label="Permalink to &quot;Принцип двух контуров: цех и карман мастера&quot;">​</a></h2><p>Финансовая архитектура программы разделяет денежные потоки на два независимых контура:</p><ol><li><strong>Операционный контур цеха (Рабочие пространства):</strong> учет складских остатков по методу скользящей средней стоимости (МАК), расчет норм расхода сырья в калькуляторе, движение партий на верстаке, кассовые ордера движения денег (ДДС) и реализация готовых изделий по методу первых партий (ФИФО).</li><li><strong>Консолидированный контур капитала (Пространство «Мой капитал»):</strong> совокупная стоимость всех активов владельца. Сюда входят наличные средства, банковские счета, накопительные депозиты, инвестиционный портфель, ценности вне производственного цеха, недвижимость, транспорт и фактические доли владения в каждом из подключенных направлений бизнеса.</li></ol><div class="info custom-block"><p class="custom-block-title">Физическая изоляция баз данных</p><p>Личные финансы хранятся в изолированном файле базы данных <code>personal_finance.db</code>. Сведения о личных счетах, инвестициях, долях и семейных резервах физически отделены от операционных баз мастерских (<code>omnicraft_erp.db</code>, <code>workspaces/*.db</code>) и никогда не попадут в производственные отчеты или акты сверки.</p></div><hr><h2 id="математическая-дельта-учет-трат-без-сбора-чеков" tabindex="-1">Математическая дельта: учет трат без сбора чеков <a class="header-anchor" href="#математическая-дельта-учет-трат-без-сбора-чеков" aria-label="Permalink to &quot;Математическая дельта: учет трат без сбора чеков&quot;">​</a></h2><p>Большинство мобильных программ для личных финансов требуют дисциплины контролера: каждый день открывать телефон и вручную заносить траты на мелкие бытовые нужды. На практике мастера хватает максимум на две недели, после чего учет забрасывается, а остатки начинают расходиться с реальностью.</p><p>В <strong>ОмниКрафт ЕРП</strong> применен обратный инженерный подход — <strong>метод расчета расходов по балансовой дельте</strong>:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Инженерный метод ОмниКрафт ЕРП</span><div class="formula-heading">Расчет личных расходов мастера по балансовой дельте</div></div><div class="formula-equation-box"><div class="math-formula-display"><span class="math-var">Личные расходы за период</span><span class="math-op">=</span><span class="math-var">Капитал на начало</span><span class="math-op">+</span><span class="math-var">Доходы цехов и дивиденды</span><span class="math-op">−</span><span class="math-var">Капитал на конец</span></div></div><div class="formula-card-bottom"><p>Мастеру достаточно 1–2 раза в месяц актуализировать фактические остатки на основных банковских картах и в кошельках. Система сопоставит полученную разницу с операциями мастерских и вычислит точную сумму личного потребления без сбора мелких чеков.</p></div></div><div class="tip custom-block"><p class="custom-block-title">Спокойный сон предпринимателя</p><p>Если остатки на личных счетах за расчетный период увеличились, а чистая прибыль мастерских подтверждена движением готовой продукции и продажами, ваше дело развивается в плюс. Если же остатки тают, система подсветит непривязанный отток средств задолго до того, как в цехе образуется кассовый разрыв.</p></div><hr><h2 id="архитектура-инструментов-пространства-«мои-капитал»" tabindex="-1">Архитектура инструментов пространства «Мой капитал» <a class="header-anchor" href="#архитектура-инструментов-пространства-«мои-капитал»" aria-label="Permalink to &quot;Архитектура инструментов пространства «Мой капитал»&quot;">​</a></h2><p>Интерфейс пространства построен в виде пятиступенчатой системы последовательного учета от ликвидности до консолидированного баланса:</p><ol class="craft-ordered-list"><li><strong>Счета и инвестиции</strong> — ликвидные денежные средства, вклады и ценные бумаги.</li><li><strong>Имущество и материалы</strong> — долгосрочные активы, оборудование и материальные запасы.</li><li><strong>Важные операции</strong> — крупные личные транзакции, внешние инвестиции и изъятия.</li><li><strong>Мой капитал</strong> — консолидированный экран совокупного благосостояния мастера.</li><li><strong>Аналитика</strong> — ретроспективные графики динамики и распределение по классам риска.</li></ol><ul class="craft-feature-list"><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Счета и инвестиции:</strong> Единый центр управления ликвидными денежными средствами. Содержит две рабочие подвкладки: <em>«Счета и кошельки»</em> (наличные, дебетовые карты, вклады, расчетная валюта и цифровые активы) и <em>«Инвестиционный портфель»</em> (акции, облигации, доходные займы, доли в проектах).</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Имущество и материалы:</strong> Реестр материальных ценностей долгосрочного пользования (оборудование вне цеха, станки в долевом владении, недвижимость, автотранспорт и личные фонды материалов).</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Важные операции:</strong> Журнал крупных личных поступлений, внешних инвестиций и целевых изъятий, оказывающих прямое влияние на совокупный баланс.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Мой капитал:</strong> Сводная контрольная инфопанель чистых активов, объединяющая личные средства и производственный капитал всех подключенных мастерских.</span></li><li><span class="craft-list-bullet"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"></polyline></svg></span><span><strong>Аналитика:</strong> Графики динамики благосостояния, сбалансированность валютной корзины и распределение активов по классам риска.</span></li></ul><hr><h2 id="двухуровневая-навигация-и-контекстные-панели-деиствии" tabindex="-1">Двухуровневая навигация и контекстные панели действий <a class="header-anchor" href="#двухуровневая-навигация-и-контекстные-панели-деиствии" aria-label="Permalink to &quot;Двухуровневая навигация и контекстные панели действий&quot;">​</a></h2><p>Интерфейс пространства спроектирован по стандарту двухуровневой информационной архитектуры без визуального шума:</p><ul><li><strong>Уровень 1 (Главная навигационная полоса):</strong> Расположена в верхней части экрана и служит исключительно для чистого переключения между пятью разделами. Верхняя строка полностью избавлена от посторонних управляющих кнопок.</li><li><strong>Уровень 2 (Контекстные панели действий каждого экрана):</strong> Все рабочие инструменты сгруппированы строго по месту их применения:</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">Экран</th><th style="text-align:left;">Расположение</th><th style="text-align:left;">Набор инструментов</th><th style="text-align:left;">Назначение</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Счета и инвестиции</strong></td><td style="text-align:left;">Напротив вкладок «Счета / Инвестиции»</td><td style="text-align:left;"><strong>«Статистика»</strong>, <strong>«Курсы»</strong>, <strong>«Настройки»</strong>, <strong>«Справка»</strong></td><td style="text-align:left;">Анализ валютной корзины, обновление курсов валют, настройка категорий счетов и руководство по ликвидным средствам.</td></tr><tr><td style="text-align:left;"><strong>Имущество и материалы</strong></td><td style="text-align:left;">Напротив фильтра категорий имущества</td><td style="text-align:left;"><strong>«🛡️ Проверить дубликаты и коллизии»</strong>, <strong>«Добавить»</strong>, <strong>«Справка»</strong></td><td style="text-align:left;">Проверка коллизий долей владения оборудованием (метод Гамильтона), выявление дубликатов ресурсов и регистрация имущества.</td></tr><tr><td style="text-align:left;"><strong>Важные операции</strong></td><td style="text-align:left;">В шапке реестра операций</td><td style="text-align:left;"><strong>«Справка»</strong></td><td style="text-align:left;">Руководство по фиксации внешних личных доходов и крупных целевых расходов.</td></tr><tr><td style="text-align:left;"><strong>Мой капитал</strong></td><td style="text-align:left;">В шапке консолидированного экрана</td><td style="text-align:left;"><strong>«Обновить»</strong>, <strong>«Справка»</strong></td><td style="text-align:left;">Мгновенный пересчет сводного капитала мастера и проверка чистых активов.</td></tr><tr><td style="text-align:left;"><strong>Аналитика</strong></td><td style="text-align:left;">В верхней строке динамики трендов</td><td style="text-align:left;"><strong>«Справка»</strong></td><td style="text-align:left;">Обзор динамики благосостояния и ретроспективный анализ стабильности капитала.</td></tr></tbody></table><hr><h2 id="регулярныи-аудит-ресурсов-оборудования-и-долеи-владения" tabindex="-1">Регулярный аудит ресурсов, оборудования и долей владения <a class="header-anchor" href="#регулярныи-аудит-ресурсов-оборудования-и-долеи-владения" aria-label="Permalink to &quot;Регулярный аудит ресурсов, оборудования и долей владения&quot;">​</a></h2><p>В структуре личного капитала мастер часто использует станки, помещения и материалы совместно с бизнесом (например, швейная машина или лазерный гравер куплены совместно с партнером, а личный автомобиль используется для развоза готовых партий). При параллельном ведении учета или ручном заведении данных могут возникать математические коллизии долей владения либо появляться дублирующие записи одного и того же актива.</p><p>В ОмниКрафт ЕРП встроен полуавтоматический инструмент аудита фондов, исключающий искажение совокупного баланса капитала.</p><h3 id="цеховая-задача-и-типичные-расхождения" tabindex="-1">Цеховая задача и типичные расхождения <a class="header-anchor" href="#цеховая-задача-и-типичные-расхождения" aria-label="Permalink to &quot;Цеховая задача и типичные расхождения&quot;">​</a></h3><p>Регулярная ревизия решает три практические задачи владельца:</p><ol><li><strong>Нормализация долей владения (100% баланс):</strong> сумма долей личного фонда, производства и сферы услуг для каждого разделяемого объекта обязана строго равняться 100.00%. Если при редактировании долей возник дисбаланс (например, <code>95%</code> или <code>105%</code>), капитал искажается.</li><li><strong>Слияние дубликатов оборудования:</strong> исключение двойного учета станков и инструментов, заведенных под схожими наименованиями в разных пространствах.</li><li><strong>Объединение дубликатов сырья:</strong> слияние параллельно созданных карточек материалов с консолидацией общего количества и расчетной себестоимости.</li></ol><h3 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h3><p>Инструмент аудита доступен при наличии зарегистрированных активов в разделе <strong>«Имущество и материалы»</strong>.</p><h3 id="пошаговыи-порядок-проведения-аудита" tabindex="-1">Пошаговый порядок проведения аудита <a class="header-anchor" href="#пошаговыи-порядок-проведения-аудита" aria-label="Permalink to &quot;Пошаговый порядок проведения аудита&quot;">​</a></h3><ol><li><strong>Запуск аудита:</strong> В пространстве «Мой капитал» перейдите на экран <strong>«Имущество и материалы»</strong> и в панели действий нажмите кнопку <strong>«🛡️ Проверить дубликаты и коллизии»</strong>.</li><li><strong>Анализ результатов в модальном окне «Аудит фондов и коллизий»:</strong><ul><li><strong>Коллизий нет:</strong> Программа выведет зеленый статус <strong>«Коллизий и дубликатов не обнаружено. Все фонды согласованы.»</strong>;</li><li><strong>Обнаружены коллизии долей:</strong> Блок <strong>«Коллизии долей владения»</strong> подсветит карточки с нарушением пропорций с указанием фактической суммы (например, <em>«Сумма долей равна 95.0% вместо 100%»</em>). Нажмите кнопку <strong>«Исправить доли (100%)»</strong> — система автоматически сбалансирует доли по математическому методу Гамильтона;</li><li><strong>Обнаружены дубликаты оборудования:</strong> В блоке <strong>«Потенциальные дубликаты оборудования»</strong> программа покажет парные карточки и критерий совпадения. Нажмите кнопку <strong>«Объединить дубликаты»</strong> для слияния записей в единую мастер-карточку;</li><li><strong>Обнаружены дубликаты материалов:</strong> В блоке <strong>«Потенциальные дубликаты сырья»</strong> система отобразит дублирующиеся складские остатки. Нажмите кнопку <strong>«Объединить дубликаты»</strong> для корректного суммирования остатков.</li></ul></li><li><strong>Фиксация результатов:</strong> Нажмите кнопку <strong>«Закрыть»</strong>. Программа моментально пересчитает чистые активы и обновит показатели капитала во всех экранных сводках.</li></ol><div class="tip custom-block"><p class="custom-block-title">Периодичность проверки</p><p>Рекомендуется запускать проверку коллизий один раз в месяц перед подведением итогового баланса капитала, а также сразу после пакетного импорта новых активов или изменения состава учредителей мастерской.</p></div><hr><h2 id="безопасность-данных-и-открытые-валютные-курсы" tabindex="-1">Безопасность данных и открытые валютные курсы <a class="header-anchor" href="#безопасность-данных-и-открытые-валютные-курсы" aria-label="Permalink to &quot;Безопасность данных и открытые валютные курсы&quot;">​</a></h2><p>Вся финансовая информация обрабатывается <strong>строго на Вашем компьютере</strong>. Программа не передает остатки счетов, суммы инвестиций или списки имущества на сторонние серверы и в облачные хранилища.</p><p>Обновление курсов валют выполняется автоматически за считанные секунды без оформления платных подписок и без ввода секретных ключей доступа. Программа напрямую опрашивает открытые шлюзы котировок (Центральный банк РФ, Европейский центральный банк, CoinGecko). При необходимости Вы можете в любой момент вручную скорректировать курс любой расчетной единицы за пару секунд или использовать ручной экспорт промпта для внешних диалоговых моделей.</p>',44))])}const v=l(g,[["render",c]]);export{b as __pageData,v as default};
